sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.showModal = false;
  c.bookingConfirmed = false;
  c.isSubmitting = false;
  c.selectedActivity = {};

  if (c.data.isLoggedIn) {
    c.data.guestName = c.data.userName;
    c.data.guestEmail = c.data.userEmail;
  }

  // Pre-select first activity if available
  if (c.data.activities && c.data.activities.length > 0) {
    c.data.selectedActivityId = c.data.activities[0].sys_id;
    c.selectedActivity = c.data.activities[0];
  }

  c.onSelectActivity = function(act) {
    c.selectedActivity = act;
    c.data.selectedActivityId = act.sys_id;
    c.data.bookingError = '';
    c.data.canBookActivity = false;
  };

  c.onInputChange = function() {
    c.data.bookingError = '';
    c.data.canBookActivity = false;
  };

  c.canSubmit = function() {
    var hasAct = !!c.data.selectedActivityId;
    var hasRes = !!(c.data.reservationNumber && c.data.reservationNumber.trim());
    if (c.data.isLoggedIn) {
      return hasAct && hasRes;
    }
    return hasAct && hasRes && !!c.data.guestName && !!c.data.guestEmail;
  };

  // Compact Clear Selection Action
  c.clearForm = function() {
    c.selectedActivity = {};
    c.data.selectedActivityId = '';
    c.data.reservationNumber = '';
    c.data.bookingError = '';
    c.data.canBookActivity = false;
    c.showModal = false;
    c.bookingConfirmed = false;

    if (!c.data.isLoggedIn) {
      c.data.guestName = '';
      c.data.guestEmail = '';
    }
  };

  c.openConfirmModal = function() {
    c.data.bookingError = '';
    if (!c.canSubmit() || c.isSubmitting) return;
    c.isSubmitting = true;
    c.data.action = 'validateActivityBooking';
    c.server.update().then(function() {
      c.isSubmitting = false;
      if (c.data.canBookActivity) {
        c.showModal = true;
        c.bookingConfirmed = false;
      } else {
        c.showModal = false;
      }
    });
  };

  c.closeModal = function() {
    c.showModal = false;
  };

  c.confirmBooking = function() {
    c.isSubmitting = true;
    c.data.action = 'bookActivity';

    c.server.update().then(function() {
      c.isSubmitting = false;
      if (c.data.bookingSuccess) {
        c.bookingConfirmed = true;
      } else {
        c.showModal = false;
      }
    });
  };

  c.resetForm = function() {
    c.clearForm();
    if (c.data.activities && c.data.activities.length > 0) {
      c.data.selectedActivityId = c.data.activities[0].sys_id;
      c.selectedActivity = c.data.activities[0];
    }
  };
};

sp_widget.css:
.hotel-sports-widget {
  background: #faf6ef;
  min-height: 100vh;
  margin: -20px -15px 0 -15px;
  padding-bottom: 60px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1a2e26;
}

.hotel-sports-widget .page-banner {
  background: #1f3a30;
  color: #ffffff;
  padding: 55px 20px 50px;
  text-align: center;
  margin-bottom: 40px;
}

.hotel-sports-widget .banner-container {
  max-width: 800px;
  margin: 0 auto;
}

.hotel-sports-widget .page-banner .eyebrow {
  display: block;
  font-size: 0.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #e6c79c;
  margin-bottom: 8px;
  font-weight: 600;
}

.hotel-sports-widget .page-banner h1 {
  font-family: Georgia, serif;
  font-size: 2.8rem;
  color: #ffffff;
  margin: 0 0 10px;
}

.hotel-sports-widget .page-banner p {
  color: rgba(255, 255, 255, 0.8);
  font-size: 1rem;
  margin: 0;
}

.hotel-sports-widget .booking-section {
  padding: 0 24px;
}

.hotel-sports-widget .booking-container {
  max-width: 1200px;
  margin: 0 auto;
}

.hotel-sports-widget .form-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 32px;
  align-items: start;
}

@media (max-width: 900px) {
  .hotel-sports-widget .form-layout {
    grid-template-columns: 1fr;
  }
}

.hotel-sports-widget .form-card {
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 12px;
  padding: 36px;
  box-shadow: 0 4px 20px rgba(31, 58, 48, 0.06);
}

.hotel-sports-widget .form-title {
  font-family: Georgia, serif;
  font-size: 2.2rem;
  color: #1f3a30;
  margin: 0 0 8px 0;
}

.hotel-sports-widget .form-sub {
  color: #6f756f;
  font-size: 1.05rem;
  margin-bottom: 24px;
}

.hotel-sports-widget .user-status-banner {
  background: #e8eee9;
  border: 1px solid #c8ded1;
  color: #1f3a30;
  padding: 12px 18px;
  border-radius: 8px;
  margin-bottom: 26px;
  font-size: 1rem;
  display: flex;
  align-items: center;
  gap: 10px;
}

.hotel-sports-widget .user-status-banner.guest {
  background: #fdf6e9;
  border-color: #f1ddb6;
  color: #8a6420;
}

/* Activity Cards List */
.hotel-sports-widget .activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hotel-sports-widget .activity-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 18px 22px;
  border: 1.5px solid #e7e1d4;
  border-radius: 10px;
  background: #faf6ef;
  cursor: pointer;
  transition: 0.2s;
  margin: 0;
}

.hotel-sports-widget .activity-card:hover {
  border-color: #1f3a30;
  background: #ffffff;
}

.hotel-sports-widget .activity-card.selected {
  border-color: #1f3a30;
  background: #ffffff;
  box-shadow: 0 0 0 2px #1f3a30;
}

.hotel-sports-widget .activity-card input[type="radio"] {
  accent-color: #1f3a30;
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.hotel-sports-widget .activity-card .info {
  flex: 1;
}

.hotel-sports-widget .activity-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: #1f3a30;
  margin: 0 0 4px;
}

.hotel-sports-widget .activity-card .when {
  font-size: 0.9rem;
  color: #6f756f;
}

.hotel-sports-widget .activity-card .rate {
  font-family: Georgia, serif;
  font-size: 1.6rem;
  color: #1f3a30;
  font-weight: 700;
}

/* Form fields */
.hotel-sports-widget .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 600px) {
  .hotel-sports-widget .form-grid {
    grid-template-columns: 1fr;
  }
}

.hotel-sports-widget .field {
  display: flex;
  flex-direction: column;
  margin-bottom: 18px;
}

.hotel-sports-widget .field.full {
  grid-column: 1 / -1;
}

.hotel-sports-widget .field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #1f3a30;
  margin-bottom: 8px;
}

.hotel-sports-widget .field label .req {
  color: #b7382d;
}

.hotel-sports-widget .field input {
  width: 100% !important;
  height: 48px !important;
  line-height: 1.4 !important;
  padding: 10px 14px !important;
  border: 1.5px solid #e7e1d4 !important;
  border-radius: 8px !important;
  background: #faf6ef !important;
  font-size: 1rem !important;
  color: #1f3a30 !important;
  box-sizing: border-box !important;
  transition: 0.2s !important;
}

.hotel-sports-widget .field input:focus {
  border-color: #1f3a30 !important;
  background: #ffffff !important;
  outline: none !important;
}

.hotel-sports-widget .field small {
  color: #6f756f;
  font-size: 0.85rem;
  margin-top: 6px;
}

/* Long, Full-Width Side-by-Side Action Buttons */
.hotel-sports-widget .form-actions-row {
  display: flex !important;
  gap: 14px !important;
  margin-top: 28px !important;
  width: 100% !important;
}

.hotel-sports-widget .btn-clear {
  flex: 0 0 160px !important;
  height: 52px !important;
  background: #ffffff !important;
  color: #5c635c !important;
  border: 1.5px solid #d9e2dc !important;
  border-radius: 8px !important;
  font-size: 0.9rem !important;
  font-weight: 700 !important;
  cursor: pointer !important;
  white-space: nowrap !important;
  transition: all 0.2s ease !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.hotel-sports-widget .btn-clear:hover {
  background: #f5f1e8 !important;
  color: #1f3a30 !important;
  border-color: #1f3a30 !important;
}

.hotel-sports-widget .btn-main {
  flex: 1 !important;
  width: 100% !important;
  height: 52px !important;
  background: #1f3a30 !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 8px !important;
  font-size: 0.95rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.5px !important;
  text-transform: uppercase !important;
  white-space: nowrap !important;
  cursor: pointer !important;
  transition: 0.2s !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.hotel-sports-widget .btn-main:hover:not(:disabled) {
  background: #162a22 !important;
}

.hotel-sports-widget .btn-main:disabled {
  background: #b2c2ba !important;
  cursor: not-allowed !important;
}

@media (max-width: 600px) {
  .hotel-sports-widget .form-actions-row {
    flex-direction: column-reverse;
  }
  .hotel-sports-widget .btn-clear,
  .hotel-sports-widget .btn-main {
    width: 100% !important;
  }
}

/* RIGHT: Dark Green Summary Card */
.hotel-sports-widget .summary {
  background: #1f3a30;
  color: #ffffff;
  border-radius: 12px;
  padding: 36px 30px;
  box-shadow: 0 6px 24px rgba(31, 58, 48, 0.2);
  position: sticky;
  top: 30px;
}

.hotel-sports-widget .summary .eyebrow {
  font-size: 0.8rem;
  letter-spacing: 1.5px;
  color: #e6c79c;
  font-weight: 600;
  margin-bottom: 6px;
}

.hotel-sports-widget .summary h3 {
  font-family: Georgia, serif;
  font-size: 1.8rem;
  color: #ffffff;
  margin: 0 0 24px 0;
}

.hotel-sports-widget .summary-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.8);
}

.hotel-sports-widget .summary-row strong {
  color: #ffffff;
  font-weight: 600;
}

.hotel-sports-widget .summary-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin: 22px 0 16px;
}

.hotel-sports-widget .summary-total span {
  font-size: 0.85rem;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #e6c79c;
  font-weight: 700;
}

.hotel-sports-widget .summary-total strong {
  font-family: Georgia, serif;
  font-size: 2.4rem;
  color: #ffffff;
  font-weight: 700;
}

.hotel-sports-widget .summary .note {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.65);
  margin-top: 18px;
  line-height: 1.4;
}

/* Alerts */
.hotel-sports-widget .alert {
  padding: 14px 18px;
  border-radius: 8px;
  font-size: 0.95rem;
  margin-bottom: 20px;
  display: flex;
  gap: 10px;
  align-items: center;
}

.hotel-sports-widget .alert.warn {
  background: #fdf6e9;
  border-left: 4px solid #d4b07c;
  color: #8a6420;
}

.hotel-sports-widget .alert.info {
  background: #e8eee9;
  border-left: 4px solid #1f3a30;
  color: #1f3a30;
}

/* Modal */
.hotel-sports-widget .custom-modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(31, 58, 48, 0.6);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.hotel-sports-widget .custom-modal {
  background: #ffffff;
  border-radius: 12px;
  max-width: 500px;
  width: 100%;
  padding: 36px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.hotel-sports-widget .dialog-body {
  padding: 0;
}

.hotel-sports-widget .dialog-total {
  font-family: Georgia, serif;
  font-size: 2.4rem;
  color: #1f3a30;
  font-weight: 700;
  margin-bottom: 20px;
}

.hotel-sports-widget .summary-row.dark {
  color: #6f756f;
  border-color: #e7e1d4;
  padding: 8px 0;
}

.hotel-sports-widget .summary-row.dark strong {
  color: #1a2e26;
}

.hotel-sports-widget .dialog-note {
  font-size: 0.85rem;
  color: #6f756f;
  margin: 18px 0 24px 0;
}

.hotel-sports-widget .dialog-actions {
  display: flex;
  gap: 14px;
}

.hotel-sports-widget .btn-outline {
  flex: 1;
  height: 48px;
  border: 1.5px solid #d9e2dc;
  background: #ffffff;
  color: #1f3a30;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}

.hotel-sports-widget .btn-green {
  flex: 1;
  height: 48px;
  background: #1f3a30;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}

.hotel-sports-widget .res-num-box {
  background: #f3f8f5;
  border: 2px dashed #79d2a6;
  border-radius: 10px;
  padding: 24px;
  text-align: center;
  margin: 20px 0;
}

.hotel-sports-widget .res-num-box small {
  font-size: 0.8rem;
  letter-spacing: 1.5px;
  color: #6f756f;
  font-weight: 700;
  text-transform: uppercase;
}

.hotel-sports-widget .res-num-box .res-num {
  font-family: Georgia, serif;
  font-size: 2.2rem;
  color: #1f3a30;
  font-weight: 700;
  margin-top: 6px;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userId = gs.getUserID();
  data.userName = gs.getUserDisplayName();
  data.userEmail = gs.getUser().getEmail() || '';

  // 1. Fetch activities with clean dates (no trailing seconds)
  data.activities = [];
  var actGr = new GlideRecord('x_2206701_hotel_0_sports_activities');
  actGr.orderBy('activity_name');
  actGr.query();

  while (actGr.next()) {
    var rawDate = '';
    if (actGr.isValidField('activity_date_and_time')) {
      rawDate = actGr.getValue('activity_date_and_time') || '';
    } else if (actGr.isValidField('u_activity_date_and_time')) {
      rawDate = actGr.getValue('u_activity_date_and_time') || '';
    }

    var cleanSchedule = rawDate;
    if (cleanSchedule && cleanSchedule.length >= 16) {
      cleanSchedule = cleanSchedule.substring(0, 16);
    }

    data.activities.push({
      sys_id: actGr.getUniqueValue(),
      name: actGr.getValue('activity_name') || 'Activity',
      rate: parseFloat(actGr.getValue('rate')) || 0,
      schedule: cleanSchedule || 'Daily'
    });
  }

  data.noActivities = (data.activities.length === 0);

  if (input) {
    data.selectedActivityId = input.selectedActivityId;
    data.reservationNumber = (input.reservationNumber || '').trim();
    data.guestName = input.guestName || (data.isLoggedIn ? data.userName : '');
    data.guestEmail = input.guestEmail || (data.isLoggedIn ? data.userEmail : '');

    // ==========================================
    // ACTION: validateActivityBooking or bookActivity
    // ==========================================
    if (input.action === 'validateActivityBooking' || input.action === 'bookActivity') {
      data.canBookActivity = false;
      data.bookingError = '';

      if (!data.reservationNumber) {
        data.bookingError = 'Please enter your room reservation number.';
        return;
      }

      // Check if room reservation exists
      var grRes = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
      grRes.addQuery('number', data.reservationNumber);
      grRes.query();

      var validRes = false;
      var resSysId = '';
      var resDisplayNum = data.reservationNumber;
      var resUserId = '';
      var resGuestName = '';

      if (grRes.next()) {
        validRes = true;
        resSysId = grRes.getUniqueValue();
        resDisplayNum = grRes.getValue('number') || data.reservationNumber;
        resUserId = grRes.getValue('registered_user') || grRes.getValue('user') || '';
        resGuestName = grRes.getValue('guest_name') || '';
      } else {
        var grResById = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        if (grResById.get(data.reservationNumber)) {
          validRes = true;
          resSysId = grResById.getUniqueValue();
          resDisplayNum = grResById.getValue('number') || data.reservationNumber;
          resUserId = grResById.getValue('registered_user') || grResById.getValue('user') || '';
          resGuestName = grResById.getValue('guest_name') || '';
        }
      }

      if (!validRes) {
        data.bookingError = 'No active room reservation found for "' + data.reservationNumber + '". A valid room reservation is required to book sports activities.';
        return;
      }

      // ==========================================
      // Enforce 1-activity rule PER RESERVATION STAY
      // ==========================================
      var grCheck = new GlideRecord('x_2206701_hotel_0_sports_bookings');
      var hasResCol = false;

      // Check against the Room Reservation reference column
      if (grCheck.isValidField('room_reservation')) {
        grCheck.addQuery('room_reservation', resSysId);
        hasResCol = true;
      } else if (grCheck.isValidField('u_room_reservation')) {
        grCheck.addQuery('u_room_reservation', resSysId);
        hasResCol = true;
      } else if (grCheck.isValidField('reservation')) {
        grCheck.addQuery('reservation', resSysId);
        hasResCol = true;
      }

      if (!hasResCol) {
        if (grCheck.isValidField('reservation_number')) {
          grCheck.addQuery('reservation_number', resDisplayNum);
        }
      }

      grCheck.addQuery('booking_status', '!=', 'cancelled');
      grCheck.query();

      if (grCheck.next()) {
        var existingNum = grCheck.getValue('number') || 'existing';
        data.bookingError = 'A sports activity is already scheduled for reservation ' + resDisplayNum + ' (' + existingNum + '). Only one activity is permitted per booking.';
        return;
      }

      data.canBookActivity = true;

      // ==========================================
      // Execute booking insert
      // ==========================================
      if (input.action === 'bookActivity') {
        var grBook = new GlideRecord('x_2206701_hotel_0_sports_bookings');
        grBook.initialize();

        // Save activity reference
        if (grBook.isValidField('sports_activity')) {
          grBook.setValue('sports_activity', data.selectedActivityId);
        } else if (grBook.isValidField('activity')) {
          grBook.setValue('activity', data.selectedActivityId);
        }

        // SAVE ROOM RESERVATION LINK INTO THE NEW COLUMN!
        if (grBook.isValidField('room_reservation')) {
          grBook.setValue('room_reservation', resSysId);
        } else if (grBook.isValidField('u_room_reservation')) {
          grBook.setValue('u_room_reservation', resSysId);
        } else if (grBook.isValidField('reservation')) {
          grBook.setValue('reservation', resSysId);
        }

        // Save user & guest info
        if (grBook.isValidField('registered_user') && data.userId) {
          grBook.setValue('registered_user', data.userId);
        }
        if (grBook.isValidField('guest_name')) {
          grBook.setValue('guest_name', data.guestName);
        }
        if (grBook.isValidField('guest_email')) {
          grBook.setValue('guest_email', data.guestEmail);
        }
        if (grBook.isValidField('booking_status')) {
          grBook.setValue('booking_status', 'Booked');
        }

        var newId = grBook.insert();
        if (newId) {
          data.bookingSuccess = true;
          var refGr = new GlideRecord('x_2206701_hotel_0_sports_bookings');
          if (refGr.get(newId)) {
            data.activityBookingRef = refGr.getValue('number') || newId;
          } else {
            data.activityBookingRef = newId;
          }
        } else {
          data.bookingSuccess = false;
          data.bookingError = 'Unable to complete sports booking. Please try again.';
        }
      }
    }
  }
})();
